import{_ as t}from"./chunks/difficulty_easy.76S4H_Nf.js";import{_ as a}from"./chunks/remote_control.ss1psCxn.js";import{_ as r}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as i}from"./chunks/position_fw.BlmoI5P4.js";import{_ as o,o as d,c as _,al as l}from"./chunks/framework.7vp1BMOE.js";const P=JSON.parse('{"title":"Cruise Mode (Fixed-Wing)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes_fw/cruise.md","filePath":"uk/flight_modes_fw/cruise.md"}'),n={name:"uk/flight_modes_fw/cruise.md"};function s(c,e,m,h,f,p){return d(),_("div",null,[...e[0]||(e[0]=[l('<h1 id="cruise-mode-fixed-wing" tabindex="-1">Cruise Mode (Fixed-Wing) <a class="header-anchor" href="#cruise-mode-fixed-wing" aria-label="Permalink to &quot;Cruise Mode (Fixed-Wing)&quot;">​</a></h1><p><img src="'+t+'" title="Easy to fly" width="30px"> <img src="'+a+'" title="Manual/Remote control required" width="30px"> <img src="'+r+'" title="Position fix required (e.g. GPS)" width="30px"></p><p><em>Cruise mode</em> (also shown as <em>Position</em> in some tools) is the easiest and safest manual mode. It is supported on vehicles that have a position estimate (e.g. GPS). Це полегшує пілотам контроль висоти транспортного засобу, і зокрема досягати і підтримувати фіксовану висоту. The mode will hold the vehicle&#39;s course against wind. Швидкість активно контролюється, якщо встановлений датчик швидкості.</p><p>The vehicle performs a <a href="https://en.wikipedia.org/wiki/Coordinated_flight" target="_blank" rel="noreferrer">coordinated turn</a> if the roll sticks are non-zero, while the pitch stick controls the rate of ascent/descent. Засувка визначає швидкість повітря — при 50% засувки літак буде утримувати свою поточну висоту з заданою крейсерською швидкістю.</p><p>When all sticks are released/centered (no roll, pitch, yaw, and ~50% throttle) the aircraft will return to straight, level flight, and keep its current altitude and flight path irrespective of wind. This makes it easy to recover from any problems when flying. Roll and pitch are angle-controlled (so it is impossible to roll over or loop the vehicle).</p><p>Стік повороту може бути використана для збільшення/зменшення кута приводу автомобіля на поворотах. Якщо контролер фіксований у центрі, то він самостійно здійснює координацію повороту, що означає, що він застосовує необхідну швидкість розвороту для поточного кута крену, щоб виконати плавний поворот. The diagram below shows the mode behaviour visually (for a <a href="./../getting_started/rc_transmitter_receiver#transmitter_modes">mode 2 transmitter</a>).</p><p><img src="'+i+'" alt="FW Cruise Mode"></p><h2 id="технічнии-опис" tabindex="-1">Технічний опис <a class="header-anchor" href="#технічнии-опис" aria-label="Permalink to &quot;Технічний опис&quot;">​</a></h2><p>Cruise mode is like <a href="./../flight_modes_fw/altitude">Altitude mode</a> but with course stabilization. Швидкість також стабілізується, якщо встановлений датчик швидкості.</p><ul><li>Центровані вхідні показники крену/тангажу/рискання (в межах дедбенду): <ul><li>Autopilot levels vehicle and maintains altitude, airspeed and course over ground.</li></ul></li><li>Зовнішній центр: <ul><li>Стік регулює висота польоту.</li><li>Резервний стік керує швидкістю літального апарату, якщо підключений датчик швидкості. Without an airspeed sensor the vehicle will fly level at trim throttle (<a href="./../advanced_config/parameter_reference#FW_THR_TRIM">FW_THR_TRIM</a>), increasing or decreasing throttle as needed to climb or descend.</li><li>Стік керування використовує кут крена. Autopilot will maintain <a href="https://en.wikipedia.org/wiki/Coordinated_flight" target="_blank" rel="noreferrer">coordinated flight</a>.</li><li>Стік крену додає додатковий значення швидкості рискання (додається до розрахованого автопілотом для підтримки координованого польоту). Може бути використаний для ручної зміни кута рискання безпілотного засобу.</li></ul></li><li>Потрібен ручний ввід управління (наприклад, за допомогою пульта дистанційного керування, джойстика).</li><li>Необхідне джерело вимірювання висоти (зазвичай барометр або GPS)</li></ul><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_alt"><code>mode_req_local_alt</code></a> — Local altitude relative to EKF2 origin (&#39;0&#39;) position</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_position_relaxed"><code>mode_req_local_position_relaxed</code></a> — Position relative to EKF2 origin (&#39;0&#39;) point but accepts poor accuracy</li><li><a href="./../flight_modes/mode_requirements#mode_req_manual_control"><code>mode_req_manual_control</code></a> — Requires stick input</li></ul><h2 id="параметри" tabindex="-1">Параметри <a class="header-anchor" href="#параметри" aria-label="Permalink to &quot;Параметри&quot;">​</a></h2><p>Режим впливає на наступні параметри:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="FW_AIRSPD_MIN"></a><a href="./../advanced_config/parameter_reference#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a></td><td>Мінімальна швидкість. За замовчуванням: 10 м/с.</td></tr><tr><td><a id="FW_AIRSPD_MAX"></a><a href="./../advanced_config/parameter_reference#FW_AIRSPD_MAX">FW_AIRSPD_MAX</a></td><td>Максимальна швидкість. За замовчуванням: 20 м/с.</td></tr><tr><td><a id="FW_AIRSPD_TRIM"></a><a href="./../advanced_config/parameter_reference#FW_AIRSPD_TRIM">FW_AIRSPD_TRIM</a></td><td>Крейсерська швидкість. За замовчуванням: 15 м/с.</td></tr><tr><td><a id="FW_MAN_P_MAX"></a><a href="./../advanced_config/parameter_reference#FW_MAN_P_MAX">FW_MAN_P_MAX</a></td><td>Установлення максимального кроку в режимі стабілізації кута нахилу. За замовчуванням: 45 градусів.</td></tr><tr><td><a id="FW_MAN_R_MAX"></a><a href="./../advanced_config/parameter_reference#FW_MAN_R_MAX">FW_MAN_R_MAX</a></td><td>Максимальне значення крена в режимі стабілізації кута нахилу. За замовчуванням: 45 градусів.</td></tr><tr><td><a id="FW_T_CLMB_R_SP"></a><a href="./../advanced_config/parameter_reference#FW_T_CLMB_R_SP">FW_T_CLMB_R_SP</a></td><td>Максимальна задана швидкість підйому. За замовчуванням: 3 м/с.</td></tr><tr><td><a id="FW_T_SINK_R_SP"></a><a href="./../advanced_config/parameter_reference#FW_T_SINK_R_SP">FW_T_SINK_R_SP</a></td><td>Максимальне значення зниження швидкості. За замовчуванням: 2 м/с.</td></tr><tr><td><a id="FW_PN_R_SLEW_MAX"></a><a href="./../advanced_config/parameter_reference#FW_PN_R_SLEW_MAX">FW_PN_R_SLEW_MAX</a></td><td>Roll setpoint slew rate limit. Default: 90 °/s.</td></tr></tbody></table><h2 id="mavlink-commands" tabindex="-1">MAVLink Commands <a class="header-anchor" href="#mavlink-commands" aria-label="Permalink to &quot;MAVLink Commands&quot;">​</a></h2><p>The following commands are relevant to this mode:</p><ul><li><p><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_CHANGE_SPEED" target="_blank" rel="noreferrer">MAV_CMD_DO_CHANGE_SPEED</a> — Sets the cruise airspeed for centred throttle stick.</p><p>This requires an airspeed sensor. Only the airspeed speed type is handled (<code>param1</code> must be <code>0</code>); other speed types are ignored. At centered throttle the vehicle holds the commanded airspeed (<code>param2</code>) if a positive value is set (non-positive values are ignored). The value is constrained between <a href="./../advanced_config/parameter_reference#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a> and <a href="./../advanced_config/parameter_reference#FW_AIRSPD_MAX">FW_AIRSPD_MAX</a>, and defaults to <a href="./../advanced_config/parameter_reference#FW_AIRSPD_TRIM">FW_AIRSPD_TRIM</a> if no airspeed has been commanded. Deflecting the throttle stick scales the airspeed toward <code>FW_AIRSPD_MIN</code> (back) or <code>FW_AIRSPD_MAX</code> (forward) around this value. The commanded airspeed resets to <code>FW_AIRSPD_TRIM</code> on every flight mode change.</p></li></ul><p>Note, other commands may be supported.</p>',20)])])}const R=o(n,[["render",s]]);export{P as __pageData,R as default};
